from pathlib import Path
import importlib.util,json
ROOT=Path(__file__).resolve().parents[1]
spec=importlib.util.spec_from_file_location('study_draw',ROOT/'scripts/ai-oop-visual-build.py')
V=importlib.util.module_from_spec(spec);spec.loader.exec_module(V)
V.OUT=ROOT/'docs/diagrams/database';V.OUT.mkdir(parents=True,exist_ok=True)
OUT=ROOT/'scripts/database-visuals.json'
REF='https://dev.mysql.com/doc/refman/8.4/en/join.html'
def draw(lesson,section,name,title,explanation,source,assumptions,model,blocks,ref=REF):
    d=V.Draw('database-management',lesson,section,name,title,explanation,source,ref,assumptions,model)
    d.d.update(id='db16-'+name,name='db16-'+name,
      verification='Independent SQL row models, PHP helper tests, and diagram-specific checks in check-database.cjs; source/technical review is recorded separately.',
      review='Original supplemental illustration; raster bounds, model and browser results documented in docs/database-visuals.md')
    d.s[0]=d.s[0].replace('STUDY / OOP','STUDY / DB • ภาพ')
    if model['kind']=='campus':
        # Real entity/FK cardinalities, not a process arrow through unrelated tables.
        for i,lines in enumerate(blocks):
            if i:
                d.text(280,d.y+22,'1 : N' if i<3 else 'N : 1',32,anchor='middle',weight=600)
                d.line([(280,d.y+32),(280,d.y+65)],V.BLUE,True);d.y+=78
            d.node(28,d.y,lines,width=504);d.y+=140
    elif model['kind']=='resume':
        d.node(28,d.y,blocks[0],width=504);d.y+=140
        d.text(280,d.y+22,'1 : N',32,anchor='middle',weight=600)
        d.line([(280,d.y+32),(280,d.y+65)],V.BLUE,True);d.y+=78
        d.node(28,d.y,blocks[1],width=504);d.y+=148
        for lines in blocks[2:]:d.card(lines)
    elif model['kind'] in ('localhost','counts','outer-filter','test-layers'):
        for lines in blocks:d.card(lines)
    else:d.flow(blocks)
    d.finish();d.d['svg']='docs/diagrams/database/'+d.d['name']+'.svg'

